// Normaliza o payload recebido do webhook (Evolution API) para um formato padrao
const body = $input.first().json.body || $input.first().json;

let result = {
  _rawBody: JSON.stringify(body).slice(0, 2000),
  _parseError: false,
  provider: 'evolution',
  _todayIso: new Date().toISOString().slice(0, 10),
  _nowIso: new Date().toISOString()
};

try {
  const data = body.data || body;
  const remoteJid = data.key ? data.key.remoteJid : (data.remoteJid || '');
  const fromMe = data.key ? data.key.fromMe : false;

  const phoneDigits = (remoteJid || '').replace(/@.*/, '').replace(/\D/g, '');

  let text = '';
  if (data.message) {
    text = data.message.conversation
      || (data.message.extendedTextMessage && data.message.extendedTextMessage.text)
      || (data.message.buttonsResponseMessage && data.message.buttonsResponseMessage.selectedDisplayText)
      || (data.message.listResponseMessage && data.message.listResponseMessage.title)
      || '';
  }
  if (!text && body.text) text = body.text;

  if (!phoneDigits || fromMe) {
    result._parseError = true;
    result._skipReason = fromMe ? 'mensagem_propria' : 'sem_telefone';
  }

  result.phoneDigits = phoneDigits;
  result.text = text;
} catch (e) {
  result._parseError = true;
  result._skipReason = 'erro_parse: ' + e.message;
}

return [{ json: result }];

